          "**",
        ],
        "changelog": [
          "@changesets/cli/changelog",
          null,
        ],
        "commit": false,
        "fixed": [],
        "format": "auto",
        "ignore": [],
        "linked": [],
        "privatePackages": {
          "tag": false,
